function readActiveRuns(repo: string, sha: string): ActiveRun[] {
  const { code, stdout, stderr } = ghRead("api", `repos/${repo}/actions/runs?head_sha=${sha}&per_page=50`);
  if (code) {
    log(`WARN could not list workflow runs for ${sha}: ${stderr || stdout}`);
    return [];
